select * from ( select s.stock_id, s.warehouse_id, s.product_id, s.location_id, s.batch_no, s.quantity, s.locked_quantity, s.frozen_quantity, s.warning_min_qty, s.warning_max_qty, s.production_date, s.expiry_date, s.version, s.create_by, s.create_time, s.update_by, s.update_time, datediff(s.expiry_date, curdate()) as remain_days, case when datediff(s.expiry_date, curdate()) < 0 then 'expired' else 'near_expiry' end as expiry_status from wms_stock s left join md_product p on s.product_id = p.product_id where s.quantity > 0 and s.expiry_date is not null and datediff(s.expiry_date, curdate()) <= coalesce(nullif(p.warning_before_days, 0), #{warningDays}, 30)
and s.warehouse_id = #{warehouseId}
and s.product_id = #{productId}
