mapper.select:
select * from ( select stock.stock_id, stock.warehouse_id, stock.product_id, stock.location_id, stock.batch_no, stock.quantity, stock.locked_quantity, stock.frozen_quantity, stock.warning_min_qty, stock.warning_max_qty, stock.version, stock.create_by, stock.create_time, stock.update_by, stock.update_time, recent_outbound.last_outbound_time, timestampdiff(day, coalesce(recent_outbound.last_outbound_time, stock.create_time), sysdate()) as unsold_days, #{warningDays} as warning_days, case when stock.quantity - ifnull(stock.locked_quantity, 0) - ifnull(stock.frozen_quantity, 0) < 0 then 'negative_available' when stock.warning_min_qty is not null and stock.quantity < stock.warning_min_qty then 'low_stock' when stock.warning_max_qty is not null and stock.warning_max_qty > 0 and stock.quantity > stock.warning_max_qty then 'over_stock' when stock.quantity > 0 and timestampdiff(day, coalesce(recent_outbound.last_outbound_time, stock.create_time), sysdate()) >= #{warningDays} then 'unsold' else 'normal' end as warning_type, case when stock.quantity - ifnull(stock.locked_quantity, 0) - ifnull(stock.frozen_quantity, 0) < 0 then '可用库存小于0，请检查锁定、冻结和库存流水' when stock.warning_min_qty is not null and stock.quantity < stock.warning_min_qty then '当前库存低于最小预警库存' when stock.warning_max_qty is not null and stock.warning_max_qty > 0 and stock.quantity > stock.warning_max_qty then '当前库存高于最大预警库存' when stock.quantity > 0 and timestampdiff(day, coalesce(recent_outbound.last_outbound_time, stock.create_time), sysdate()) >= #{warningDays} then '超过预警天数未发生出库' else '库存正常' end as warning_message from wms_stock stock left join ( select warehouse_id, product_id, location_id, batch_no, max(create_time) as last_outbound_time from wms_stock_log where in_out = '2' and bill_type not in ('stock_freeze', 'stock_unfreeze') group by warehouse_id, product_id, location_id, batch_no ) recent_outbound on recent_outbound.warehouse_id = stock.warehouse_id and recent_outbound.product_id = stock.product_id and recent_outbound.location_id = stock.location_id and ifnull(recent_outbound.batch_no, '') = ifnull(stock.batch_no, '')
and stock.warehouse_id = #{warehouseId}
and stock.product_id = #{productId}
and stock.location_id = #{locationId}
and stock.batch_no = #{batchNo}
${params.warehouseScope}
) risk_stock where risk_stock.warning_type != 'normal'
and risk_stock.warning_type = #{warningType}
order by case risk_stock.warning_type when 'negative_available' then 1 when 'low_stock' then 2 when 'over_stock' then 3 when 'unsold' then 4 else 9 end, risk_stock.create_time desc

