update wms_stock
warehouse_id = #{warehouseId}, product_id = #{productId}, location_id = #{locationId}, batch_no = #{batchNo}, quantity = #{quantity}, locked_quantity = #{lockedQuantity}, frozen_quantity = #{frozenQuantity}, warning_min_qty = #{warningMinQty}, warning_max_qty = #{warningMaxQty}, production_date = #{productionDate}, expiry_date = #{expiryDate}, version = ifnull(version, 0) + 1, update_by = #{updateBy}, update_time = sysdate()
where stock_id = #{stockId}

update wms_stock

    warning_min_qty = case
        when warning_min_qty is null or warning_min_qty = #{originalWarningMinQty} then #{warningMinQty}
        else warning_min_qty
    end,
    warning_max_qty = case
        when warning_max_qty is null or warning_max_qty = #{originalWarningMaxQty} then #{warningMaxQty}
        else warning_max_qty
    end,
    update_time = sysdate()

where product_id = #{productId}
